/* ---------- dbo.sellListingAttributes — 3 filas ---------- */
INSERT INTO [dbo].[sellListingAttributes] ([sellListingId], [attributesJson], [attributesHash], [updatedAt]) VALUES
(40, N'{"brand": "Apple", "captured_at_utc": "2026-02-23T18:55:31Z", "channel_item_id": "MLM1054106937", "currency": "MXN", "id_source": "product_id", "item_id": null, "jsonld": {"@context": "https://schema.org", "@type": "Product", "name": "Apple iPhone 17 Pro Max (256 GB) - Color plata - S\u00f3lo eSIM - Distribuidor Autorizado", "offers": {"price": 30999, "priceCurrency": "MXN"}, "aggregateRating": {"ratingValue": 4.9, "ratingCount": 1269}}}', 0x930DBA8B2D53890F6B7A4688B955E3A02A6EFD3722DD8DF2311DD795D1E14B24, '2026-02-24T01:54:48.000'),
(58, N'{"jsonld": {"name": "Celular Samsung Galaxy Z Fold 7 Negro Azabache", "image": "https://http2.mlstatic.com/D_NQ_NP_717815-MLA99413423134_112025-O.webp", "offers": {"price": 31998, "availability": "https://schema.org/InStock", "url": "https://www.mercadolibre.com.mx/celular-samsung-galaxy-z-fold-7-negro-azabache/p/MLM52050903", "@type": "Offer", "priceCurrency": "MXN", "priceValidUntil": "2026-02-27", "hasMerchantReturnPolicy": {"@type": "MerchantReturnPolicy", "applicableCountry": "MX", "returnPolicyCategory": "https://schema.org/MerchantReturnFiniteReturnWindow", "merchantReturnDays": 30, "returnMethod": "https://schema.org/ReturnByMail", "returnFees": "https://schema.org/FreeReturn"}}, "review": [{"author": {"name": "Usuario de Mercado Libre", "@type": "Person"}, "@type": "Review", "reviewBody": "Dise\u00f1o: materiales.\nBuen celular lo recomiendo.", "reviewRating": {"bestRating": 5, "ratingValue": 5, "worstRating": 1}}, {"author": {"name": "Usuario de Mercado Libre", "@type": "Person"}, "@type": "Review", "reviewBody": "", "reviewRating": {"bestRating": 5, "ratingValue": 5, "worstRating": 1}}, {"author": {"name": "Usuario de Mercado Libre", "@type": "Person"}, "@type": "Review", "reviewBody": "He tenido muchos celulares. Especialmente de apple, pero nunca hab\u00eda tenido uno como este, el galaxy fold 7 rompe todas las barreras conocidas y te da una experiencia \u00fanica y sorprendente. En mi caso me gusta ver contenidos en pantalla grande, pero andarla cargando es un fastidio, con este, tienes un celular cuyo tama\u00f1o es entre el iphone 15 y el iphone 16 pro max, pero cuando se despliega tienes una pantalla de 8 pulgadas incre\u00edble. Adem\u00e1s, la c\u00e1mara est\u00e1 padr\u00edsima y hace miles de cosas que pasar\u00e1s semanas descubriendo, la verdad hace a\u00f1os que no dec\u00eda wow! al recibir un tel\u00e9fono. Tus amigos se sorprender\u00e1n al verte desplegar la pantalla, aprovecha los descuentos. Cuesta regularmente 48 pero aqu\u00ed lo consegu\u00edan en 29, lo cual es el mismo precio que el nuevo iphone 17 promax. Inclusive m\u00e1s barato y tienes un celular minitablet que hace miles de cosas m\u00e1s que el iphone y mira que soy fan de apple, jam\u00e1s pens\u00e9 decir esto. Obvio si tienes todo tu ecosistema en apple, te va a costar un poquito de trabajo cambiarte, pero vale much\u00edsimo la pena. Actualizaci\u00f3n!, mi fold 7 fue la sensaci\u00f3n en las fiestas de fin de a\u00f1o, todos me lo ped\u00edan para verlo, se maravillaron de la pantalla y lo incre\u00edblemente delgado, siempre tengo lo \u00faltimo pero nunca me hab\u00eda pasado que se sorprendieran con un celular!.", "reviewRating": {"bestRating": 5, "ratingValue": 5, "worstRating": 1}}, {"author": {"name": "Usuario de Mercado Libre", "@type": "Person"}, "@type": "Review", "reviewBody": "C\u00e1mara: la camara excelente aunque note que no tiene el sensor de los galacy s.\nBater\u00eda: la bater\u00eda dura bien en pantalla sencilla pero dura poco en la pantalla doble.\nCreo que en lo personal si me gusta m\u00e1s que el s24 ultra para trabajar pero como celular esta mejor el s25 ultra.", "reviewRating": {"bestRating": 5, "ratingValue": 5, "worstRating": 1}}, {"author": {"name": "Usuario de Mercado Libre", "@type": "Person"}, "@type": "Review", "reviewBody": "Excelente celular.", "reviewRating": {"bestRating": 5, "ratingValue": 5, "worstRating": 1}}], "description": "Memoria RAM: 12 GB. | Dispositivo desbloqueado para que elijas la compa\u00f1\u00eda telef\u00f3nica que prefieras. | Compatible con redes 5G. | Tiene 3 c\u00e1maras traseras de 200 MP. | C\u00e1mara delantera de 10Mpx. | Bater\u00eda de 4.4 Ah. | Memoria interna de 512GB.  | A prueba de agua. | Con reconocimiento facial y sensor de huella dactilar. | Resistente al polvo y a las ca\u00eddas.", "brand": "Samsung", "sku": "MLM52050903", "weight": "455 g", "width": "16.23 cm", "height": "2.75 cm", "color": "Negro", "@context": "https://schema.org", "@type": "Product", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 4.9, "ratingCount": 74, "reviewCount": 43}, "itemCondition": "https://schema.org/NewCondition", "productID": "MLM52050903"}}', 0x9416E965C6FB2EA80FB96436C945901FA68875F5BC1426CADAFD3EE8673A45F9, '2026-02-24T19:39:21.000'),
(62, N'{"jsonld": {"name": "Samsung Galaxy Z Fold7 Sombra Azul 1tb Sombra Azul (Nuevo con caja abierta)", "image": "https://http2.mlstatic.com/D_NQ_NP_996754-MLA98736262653_112025-O.webp", "offers": {"price": 37999, "availability": "https://schema.org/InStock", "url": "https://www.mercadolibre.com.mx/samsung-galaxy-z-fold7-sombra-azul-1tb-sombra-azul-nuevo-con-caja-abierta/p/MLM2049141923", "@type": "Offer", "priceCurrency": "MXN", "priceValidUntil": "2026-02-27", "hasMerchantReturnPolicy": {"@type": "MerchantReturnPolicy", "applicableCountry": "MX", "returnPolicyCategory": "https://schema.org/MerchantReturnFiniteReturnWindow", "merchantReturnDays": 30, "returnMethod": "https://schema.org/ReturnByMail", "returnFees": "https://schema.org/FreeReturn"}}, "review": [{"author": {"name": "Usuario de Mercado Libre", "@type": "Person"}, "@type": "Review", "reviewBody": "Excelente producto.", "reviewRating": {"bestRating": 5, "ratingValue": 5, "worstRating": 1}}], "description": "El producto es nuevo y est\u00e1 en perfecto estado. | Incluye sus accesorios originales.", "brand": "Samsung", "sku": "MLM2049141923", "width": "14.32 cm", "height": "15.84 cm", "color": "Azul", "@context": "https://schema.org", "@type": "Product", "aggregateRating": {"@type": "AggregateRating", "ratingValue": 5, "ratingCount": 2, "reviewCount": 1}, "productID": "MLM2049141923"}}', 0xA6EE1758C4F6EF4610D5FE6ACD991E68E8C410C724A9728A690EA9FAB11E2EA1, '2026-02-24T19:20:39.000');
